/* The tokens and shared rules of Rosepetal's design: the one source. Apps import this after Tailwind's theme and utilities. */
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));
@custom-variant short (@media (max-height: 56rem));

@theme inline {
  @keyframes accordion-down {
    from {
      height: 0;
    }
    to {
      height: var(--reka-accordion-content-height, var(--accordion-panel-height, auto));
    }
  }

  @keyframes accordion-up {
    from {
      height: var(--reka-accordion-content-height, var(--accordion-panel-height, auto));
    }
    to {
      height: 0;
    }
  }
}

@custom-variant data-open {
  &:where([data-state="open"]),
  &:where([data-open]:not([data-open="false"])) {
    @slot;
  }
}

@custom-variant data-closed {
  &:where([data-state="closed"]),
  &:where([data-closed]:not([data-closed="false"])) {
    @slot;
  }
}

@custom-variant data-checked {
  &:where([data-state="checked"]),
  &:where([data-checked]:not([data-checked="false"])) {
    @slot;
  }
}

@custom-variant data-unchecked {
  &:where([data-state="unchecked"]),
  &:where([data-unchecked]:not([data-unchecked="false"])) {
    @slot;
  }
}

@custom-variant data-selected {
  &:where([data-selected="true"]) {
    @slot;
  }
}

@custom-variant data-disabled {
  &:where([data-disabled="true"]),
  &:where([data-disabled]:not([data-disabled="false"])) {
    @slot;
  }
}

@custom-variant data-active {
  &:where([data-state="active"]),
  &:where([data-active]:not([data-active="false"])) {
    @slot;
  }
}

@custom-variant data-horizontal {
  &:where([data-orientation="horizontal"]) {
    @slot;
  }
}

@custom-variant data-vertical {
  &:where([data-orientation="vertical"]) {
    @slot;
  }
}

@utility no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;

  &::-webkit-scrollbar {
    display: none;
  }
}

@utility scrollbar-thumb-transparent {
  --tw-scrollbar-thumb: transparent;
  scrollbar-color: var(--tw-scrollbar-thumb) var(--tw-scrollbar-track, transparent);

  &::-webkit-scrollbar-thumb {
    background-color: transparent;
  }
}

@utility scrollbar-track-transparent {
  --tw-scrollbar-track: transparent;
  scrollbar-color: var(--tw-scrollbar-thumb, transparent) var(--tw-scrollbar-track);

  &::-webkit-scrollbar-track {
    background-color: transparent;
  }
}

@utility no-scrollbar {
  -ms-overflow-style: none;
  scrollbar-width: none;

  &::-webkit-scrollbar {
    display: none;
  }
}

@utility scrollbar-thumb-transparent {
  --tw-scrollbar-thumb: transparent;
  scrollbar-color: var(--tw-scrollbar-thumb) var(--tw-scrollbar-track, transparent);

  &::-webkit-scrollbar-thumb {
    background-color: transparent;
  }
}

@utility scrollbar-track-transparent {
  --tw-scrollbar-track: transparent;
  scrollbar-color: var(--tw-scrollbar-thumb, transparent) var(--tw-scrollbar-track);

  &::-webkit-scrollbar-track {
    background-color: transparent;
  }
}

@theme {
  --text-xs--line-height: 1rem;
  --text-sm--line-height: 1.25rem;
  --text-base--line-height: 1.5rem;
  --text-lg--line-height: 1.75rem;
  --text-xl--line-height: 1.75rem;
  --text-2xl--line-height: 2rem;
  --text-3xl--line-height: 2.25rem;
  --text-4xl--line-height: 2.5rem;
  --text-5xl--line-height: 1;
  --text-6xl--line-height: 1;
  --text-7xl--line-height: 1;
  --text-8xl--line-height: 1;
  --text-9xl--line-height: 1;
}

@theme inline {
